const references=[
{name:'Medplum',sector:'Healthcare',type:'Clinical application platform',description:'A healthcare platform with FHIR-based data tools and clinical application building blocks.',site:'https://www.medplum.com/',repo:'https://github.com/medplum/medplum',creator:'Medplum & contributors',license:'Apache-2.0 core',slug:'medplum'},
{name:'OpenEMR',sector:'Healthcare',type:'Electronic health records',description:'An open-source electronic health record and practice-management system.',site:'https://www.open-emr.org/',repo:'https://github.com/openemr/openemr',creator:'OpenEMR community',license:'GPL-3.0',slug:'openemr'},
{name:'Moodle',sector:'Education',type:'Learning management system',description:'An online learning platform for organizing courses, assignments, and learning activities.',site:'https://moodle.com/',repo:'https://github.com/moodle/moodle',creator:'Moodle & contributors',license:'GPL-3.0 · LMS',slug:'moodle'},
{name:'Chamilo',sector:'Education',type:'E-learning platform',description:'A learning management platform focused on accessible course delivery and ease of use.',site:'https://chamilo.org/en/',repo:'https://github.com/chamilo/chamilo-lms',creator:'Chamilo community',license:'GPL-3.0+',slug:'chamilo'},
{name:'BigBlueButton',sector:'Education',type:'Virtual classroom',description:'A web-based classroom with video, shared whiteboards, presentations, and collaboration tools.',site:'https://bigbluebutton.org/',repo:'https://github.com/bigbluebutton/bigbluebutton',creator:'BigBlueButton & contributors',license:'LGPL-3.0',slug:'bigbluebutton'},
{name:'Saleor',sector:'Commerce',type:'Headless commerce platform',description:'A GraphQL-based commerce platform for building customized shopping experiences.',site:'https://saleor.io/',repo:'https://github.com/saleor/saleor',creator:'Saleor Commerce & contributors',license:'BSD-3-Clause core',slug:'saleor'},
{name:'Medusa',sector:'Commerce',type:'Commerce development platform',description:'Modular commerce building blocks for tailored storefronts and back-office workflows.',site:'https://medusajs.com/',repo:'https://github.com/medusajs/medusa',creator:'Medusa & contributors',license:'MIT core · open-core model',slug:'medusa'},
{name:'ERPNext',sector:'Business',type:'Enterprise resource planning',description:'An ERP platform spanning business operations, inventory, and accounting workflows.',site:'https://frappe.io/erpnext',repo:'https://github.com/frappe/erpnext',creator:'Frappe & contributors',license:'GPL-3.0',slug:'erpnext'},
{name:'Dolibarr',sector:'Business',type:'ERP & CRM',description:'A business-management suite for contacts, quotations, orders, inventory, and invoicing.',site:'https://www.dolibarr.org/',repo:'https://github.com/Dolibarr/dolibarr',creator:'Dolibarr community',license:'GPL-3.0+',slug:'dolibarr'},
{name:'Documenso',sector:'Business',type:'Document signing',description:'An open-source approach to digital document signatures and signing workflows.',site:'https://documenso.com/',repo:'https://github.com/documenso/documenso',creator:'Documenso & contributors',license:'AGPL-3.0 core',slug:'documenso'}
];
const referenceGrid=document.querySelector('#projects');references.forEach(p=>{const card=document.createElement('article');card.className='project reference-card';card.dataset.sector=p.sector;card.dataset.category=p.sector==='Commerce'?'Retail':p.sector;card.innerHTML=`<a href="${p.site}" target="_blank" rel="noopener" class="reference-preview" aria-label="View ${p.name} official website (opens in a new tab)"><div class="project-art live-preview"><div class="preview-toolbar" aria-hidden="true"><i></i><i></i><i></i><span>${new URL(p.site).hostname}</span><b>↗</b></div><img src="assets/ref-${p.slug}.jpg" alt="${p.name} official product website preview" loading="lazy" decoding="async" width="1265" height="712"><span class="preview-visit">Official website ↗</span></div></a><div class="reference-content"><span class="reference-label">Third-party reference</span><small>${p.sector} / ${p.type}</small><h3>${p.name}</h3><p>${p.description}</p><div class="reference-credit">Created by ${p.creator}<br><span>${p.license}</span></div><div class="reference-actions"><a href="${p.site}" target="_blank" rel="noopener">Visit website ↗</a><a href="${p.repo}" target="_blank" rel="noopener">Source & license ↗</a></div></div>`;referenceGrid.append(card)});